from collections import deque

g = {1: [2, 3], 2: [4], 3: [4], 4: []}

order, q, seen = [], deque([1]), {1}
while q:
    u = q.popleft()              # FIFO: explore level by level
    order.append(u)
    for v in g[u]:
        if v not in seen:
            seen.add(v)          # mark on enqueue: no duplicates
            q.append(v)
print(order)                     # [1, 2, 3, 4]

g = {1: [2, 3], 2: [4], 3: [], 4: []}

order, stack, seen = [], [1], set()
while stack:
    u = stack.pop()              # LIFO: dive deep first
    if u in seen:
        continue
    seen.add(u)
    order.append(u)
    stack.extend(reversed(g[u])) # reversed keeps left-to-right visiting
print(order)                     # [1, 2, 4, 3]

from collections import deque

g = {1: [2, 3], 2: [4], 3: [4], 4: []}
indeg = {u: 0 for u in g}
for u in g:
    for v in g[u]:
        indeg[v] += 1

q = deque(sorted(u for u in g if indeg[u] == 0))
order = []
while q:
    u = q.popleft()
    order.append(u)
    for v in g[u]:
        indeg[v] -= 1
        if indeg[v] == 0:
            q.append(v)

print(order if len(order) == len(g) else "cycle")

from collections import deque

def hop_path(graph, source, target):
    parent = {source: None}
    queue = deque([source])
    while queue:
        u = queue.popleft()
        if u == target:
            path = []
            while u is not None:
                path.append(u)
                u = parent[u]
            return list(reversed(path))
        for v in graph.get(u, []):
            if v not in parent:
                parent[v] = u
                queue.append(v)
    return None

graph = {'A': ['B', 'C'], 'B': ['D'], 'C': ['D'], 'D': []}
assert hop_path(graph, 'A', 'D') == ['A', 'B', 'D']
assert hop_path(graph, 'D', 'A') is None
print(hop_path(graph, 'A', 'D'))  # ['A', 'B', 'D']

